CREATE TABLE users(id uuid PRIMARY KEY, name text, credits numeric(10,2) NOT NULL DEFAULT 0, updated_at timestamp DEFAULT now());
CREATE TABLE challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text,description text,category text,duration text,difficulty text,min_stake numeric(8,2),max_stake numeric(8,2),host_id uuid REFERENCES users(id),host_contribution numeric(8,2) DEFAULT 0,entry_fee_percentage numeric(4,2) DEFAULT 5,failed_stake_cut numeric(4,2) DEFAULT 20,start_date timestamp,end_date timestamp,status text,verification_type text,proof_requirements jsonb,rules text[],created_at timestamp DEFAULT now(),updated_at timestamp DEFAULT now());
CREATE TABLE challenge_participants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),challenge_id uuid REFERENCES challenges(id),user_id uuid REFERENCES users(id),stake_amount numeric(8,2),entry_fee_paid numeric(8,2),insurance_purchased boolean DEFAULT false,insurance_fee_paid numeric(4,2) DEFAULT 0,completion_status text DEFAULT 'active',verification_status text DEFAULT 'pending',proof_submitted boolean DEFAULT false,reward_earned numeric(8,2) DEFAULT 0,joined_at timestamp DEFAULT now(),completed_at timestamp);
CREATE TABLE proof_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid());
CREATE TABLE credit_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),amount numeric(10,2),transaction_type text,related_challenge_id uuid REFERENCES challenges(id),description text,created_at timestamp DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),type text,title text,message text,action_url text,metadata jsonb,read boolean,created_at timestamp DEFAULT now());
